// src/pages/Institutions.jsx
import React, { useEffect, useState } from "react";
import axios from "axios";

const BASE_URL = "http://localhost:5000/api";

const Institutions = () => {
  const [institutions, setInstitutions] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    const fetchInstitutions = async () => {
      setLoading(true);
      setError("");

      try {
        const res = await axios.get(`${BASE_URL}/institutions`);
        setInstitutions(res.data);
      } catch (err) {
        console.error("Error fetching institutions", err);
        setError(err.response?.data?.error || "Failed to fetch institutions");
      } finally {
        setLoading(false);
      }
    };

    fetchInstitutions();
  }, []);

  if (loading) return <p>Loading institutions...</p>;
  if (error) return <p style={{ color: "red" }}>{error}</p>;

  return (
    <div>
      <h2>Institutions</h2>
      <ul>
        {institutions.map(inst => (
          <li key={inst.id}>{inst.name || inst.email}</li>
        ))}
      </ul>
    </div>
  );
};

export default Institutions;
